function applyPageMeta(){
 var slug=document.body.getAttribute('data-story-slug');
 var lang=(window.I18N&&window.I18N.lang())||'ar';
 var meta=pageMeta[slug]&&pageMeta[slug][lang];
 if(!meta)return;
 document.title=meta[0];
 [['meta[name="description"]',meta[1]],['meta[property="og:title"]',meta[0]],['meta[property="og:description"]',meta[1]]].forEach(function(pair){
  var node=document.querySelector(pair[0]);if(node)node.setAttribute('content',pair[1]);
 });
}
document.addEventListener('DOMContentLoaded',applyPageMeta);
document.addEventListener('site-language-change',applyPageMeta);
if(document.readyState!=='loading')applyPageMeta();

function applyTranslationNotice(lang){
 var existing=document.getElementById('ai-translation-notice');
 if(lang==='ar'){
  if(existing)existing.remove();
  return;
 }
 var copy={
  en:{
   title:'Translation notice',
   body:'This page was translated from Arabic with the assistance of artificial intelligence (AI). The translation is provided for general information and accessibility; it may contain errors or omissions. The original Arabic text is the reference version. Please consult the cited sources when checking historical details.'
  },
  fr:{
   title:'Avis de traduction',
   body:'Cette page a été traduite de l’arabe avec l’aide de l’intelligence artificielle (IA). Cette traduction est fournie à titre informatif et pour faciliter l’accès au contenu ; elle peut comporter des erreurs ou des omissions. Le texte arabe original fait foi. Veuillez consulter les sources citées pour vérifier les détails historiques.'
  },
  it:{
   title:'Avviso sulla traduzione',
   body:'Questa pagina è stata tradotta dall’arabo con l’aiuto dell’intelligenza artificiale (IA). La traduzione è fornita a scopo informativo e per facilitare l’accesso ai contenuti; potrebbe contenere errori o omissioni. Il testo originale in arabo è la versione di riferimento. Per verificare i dettagli storici, consulta le fonti citate.'
  },
  de:{
   title:'Hinweis zur Übersetzung',
   body:'Diese Seite wurde mit Unterstützung künstlicher Intelligenz (KI) aus dem Arabischen übersetzt. Die Übersetzung dient der allgemeinen Information und besseren Zugänglichkeit; sie kann Fehler oder Auslassungen enthalten. Maßgeblich ist der arabische Originaltext. Bitte prüfe historische Einzelheiten anhand der angegebenen Quellen.'
  }
 };
 var text=copy[lang];
 if(!text)return;
 if(!existing){
  existing=document.createElement('aside');
  existing.id='ai-translation-notice';
  existing.setAttribute('role','note');
  existing.style.cssText='box-sizing:border-box;width:calc(100% - 32px);max-width:900px;margin:24px auto 30px;padding:16px 20px;border:1px solid rgba(227,189,120,.42);border-left:4px solid #e3bd78;border-radius:12px;background:linear-gradient(135deg,rgba(12,35,45,.96),rgba(3,13,19,.98));color:#d9e3e4;font:400 .88rem/1.8 Arial,sans-serif;direction:ltr;text-align:left;box-shadow:0 10px 28px rgba(0,0,0,.22);';
  var heading=document.createElement('strong');
  heading.style.cssText='display:block;margin-bottom:7px;font-weight:700;color:#e3bd78;font-size:.78rem;letter-spacing:.04em;text-transform:uppercase;';
  heading.setAttribute('data-notice-title','');
  var paragraph=document.createElement('p');
  paragraph.style.cssText='margin:0;color:#d9e3e4;';
  paragraph.setAttribute('data-notice-body','');
  existing.appendChild(heading);
  existing.appendChild(paragraph);
  var footer=document.querySelector('footer');
  if(footer&&footer.parentNode)footer.parentNode.insertBefore(existing,footer.nextSibling);
  else document.body.appendChild(existing);
 }
 existing.querySelector('[data-notice-title]').textContent=text.title;
 existing.querySelector('[data-notice-body]').textContent=text.body;
}
/* Ergänzende deutsche Fassungen für nachträglich eingefügte Abschnitte in den Oktober-Geschichten 001–003. */
var germanStoryText = {
  "الصف الأول الإعدادي": "1. Klasse der Sekundarstufe I",
  "صورة من المعركة البحرية": "Ein Bild aus dem Seekrieg",
  "المدمرة «إيلات»: لماذا كانت واقعة مهمة؟": "Der Zerstörer „Eilat“: Warum war dieser Vorfall wichtig?",
  "المدمرة «إيلات»؛ صورة للسفينة نفسها وليست صورة لحظة إغراقها.": "Der Zerstörer „Eilat“; das Bild zeigt das Schiff selbst, nicht den Moment seiner Versenkung.",
  "المصدر والترخيص:": "Quelle und Lizenz:",
  "، ترخيص CC BY-SA 3.0.": "; Lizenz: CC BY-SA 3.0.",
  "في 21 أكتوبر 1967، بعد أشهر من حرب يونيو، هاجمت زوارق صواريخ مصرية المدمرة «إيلات» قبالة ساحل بورسعيد. وتُعد الواقعة من الأحداث البارزة في تاريخ استخدام الصواريخ سطح–سطح ضد سفينة حربية كبيرة؛ فقد أظهرت أن حجم السفينة وحده لا يحسم المواجهة، وأن التدريب والاستطلاع واختيار السلاح المناسب قد تغيّر ميزان القوة.": "Am 21. Oktober 1967, einige Monate nach dem Junikrieg, griffen ägyptische Raketenboote den Zerstörer „Eilat“ vor der Küste von Port Said an. Der Vorfall gilt als bedeutendes Beispiel für den Einsatz von Seezielflugkörpern gegen ein großes Kriegsschiff. Er zeigte, dass nicht allein die Größe eines Schiffes über eine Konfrontation entscheidet: Ausbildung, Aufklärung und die Wahl der passenden Waffe können das Kräfteverhältnis verändern.",
  "من المهم ألا نخلط بين هذه الواقعة وحرب أكتوبر 1973: إغراق «إيلات» حدث قبل الحرب بست سنوات تقريبًا، لكنه جزء من الخبرة التي تراكمت لدى البحرية المصرية خلال مرحلة الصراع التي سبقت أكتوبر.": "Wichtig ist, diesen Vorfall nicht mit dem Oktoberkrieg von 1973 zu verwechseln: Die Versenkung der „Eilat“ ereignete sich etwa sechs Jahre zuvor. Sie gehört jedoch zu den Erfahrungen, die die ägyptische Marine in der Zeit vor Oktober sammelte.",
  "كيف تُقرأ الخريطة البحرية؟": "Wie liest man eine Seekarte?",
  "الممرات البحرية جزء من خطة الحرب": "Seewege sind Teil der Kriegsplanung",
  "البحر ليس مساحة فارغة بين دولتين؛ فالمضائق والموانئ وخطوط الملاحة تؤثر في نقل الوقود والبضائع والإمدادات. ويقع باب المندب عند المدخل الجنوبي للبحر الأحمر، بينه وبين خليج عدن، ولذلك فإن التأثير في حركة السفن المتجهة إلى إيلات كان له معنى استراتيجي يتجاوز المسافة الجغرافية.": "Das Meer ist kein leerer Raum zwischen zwei Staaten. Meerengen, Häfen und Schifffahrtsrouten beeinflussen den Transport von Treibstoff, Waren und Nachschub. Die Meerenge Bab al-Mandab liegt am südlichen Eingang des Roten Meeres zwischen diesem und dem Golf von Aden. Deshalb hatte eine Beeinflussung des Schiffsverkehrs in Richtung Eilat eine strategische Bedeutung, die über die geografische Entfernung hinausging.",
  "توضح هذه المهمة أن العمليات العسكرية لا تقتصر على خط الجبهة الذي تظهره الصور عادة. فقد تعمل قوة في مكان بعيد لتقييد حركة الخصم أو لحماية خطوط الإمداد، وتحتاج هذه المهمة إلى تخطيط مسبق واتصالات منضبطة وفهم دقيق للممرات البحرية.": "Dieser Einsatz zeigt, dass militärische Operationen nicht auf die Frontlinie beschränkt sind, die auf Bildern meist zu sehen ist. Eine Einheit kann weit entfernt eingesetzt werden, um die Bewegungsfreiheit des Gegners einzuschränken oder Nachschubwege zu schützen. Dafür braucht es vorausschauende Planung, zuverlässige Kommunikation und genaue Kenntnisse der Seewege.",
  "وعند دراسة هذه الوقائع، ينبغي التمييز بين ما تؤكده الوثائق والروايات المتعددة وبين التفاصيل التي تختلف فيها المصادر، خصوصًا عند الحديث عن مدى السيطرة على الممرات أو نتائج العمليات.": "Bei der Untersuchung solcher Ereignisse sollte man zwischen Angaben unterscheiden, die durch Dokumente und mehrere Berichte gestützt werden, und Einzelheiten, bei denen sich die Quellen widersprechen – besonders bei Aussagen über die Kontrolle von Seewegen oder die Ergebnisse von Operationen.",
  "تحدّي خالدون": "Die Khaledoon-Challenge",
  "اختبر معلوماتك": "Teste dein Wissen",
  "اختبر معلوماتك عن الشخصية وعصرها. كل اختبار يتضمن خمسة أسئلة، مع نتيجة ومراجعة للإجابات في النهاية.": "Teste dein Wissen über die Persönlichkeit und ihre Zeit. Jeder Test enthält fünf Fragen. Am Ende erhältst du ein Ergebnis und kannst die Antworten überprüfen.",
  "الأسئلة متاحة بالعربية حاليًا.": "Die Fragen sind derzeit nur auf Arabisch verfügbar.",
  "ابدأ الاختبار": "Test starten",
  "❤️ أعجبتني": "❤️ Diese Geschichte gefällt mir",
  "صورة أرشيفية": "Archivfoto",
  "عبور خط بارليف": "Überquerung der Bar-Lev-Linie",
  "جنود مصريون خلال اقتحام خط بارليف في أكتوبر 1973.": "Ägyptische Soldaten beim Durchbruch durch die Bar-Lev-Linie im Oktober 1973.",
  "المصدر: الأهرام، عبر": "Quelle: Al-Ahram, über",
  "؛ توضح صفحة الملف حالة حقوق الصورة في مصر.": "; die Dateiseite erläutert den urheberrechtlichen Status des Bildes in Ägypten.",
  "لماذا كان الساتر صعبًا؟": "Warum war der Sandwall so schwer zu überwinden?",
  "لم تكن المشكلة مجرد إزالة كمية من الرمال؛ فقد كان الساتر طويلًا ومرتفعًا، وكان فتح ممرات كثيرة في وقت قصير ضروريًا لعبور الأفراد والمركبات والمعدات. وأي تأخير في تجهيز الممرات كان سيؤثر في حركة القوات التي تنتظر العبور.": "Die Herausforderung bestand nicht nur darin, Sand zu entfernen: Der Wall war lang und hoch. In kurzer Zeit mussten zahlreiche Durchgänge geöffnet werden, damit Soldaten, Fahrzeuge und Ausrüstung passieren konnten. Jede Verzögerung bei der Vorbereitung hätte die Bewegung der wartenden Truppen beeinträchtigt.",
  "تُنسب الفكرة الشهيرة إلى المهندس المصري باقي زكي يوسف، الذي اقترح الاستفادة من مضخات المياه ذات التدفق القوي لتجريف أجزاء من الساتر بدل الاعتماد على التفجير أو الحفر اليدوي وحدهما. وتكمن قيمة الفكرة في تحويل عائق ضخم إلى مشكلة هندسية يمكن التعامل معها على مراحل.": "Die bekannte Idee wird dem ägyptischen Ingenieur Baki Zaki Youssef zugeschrieben. Er schlug vor, leistungsstarke Wasserpumpen einzusetzen, um Teile des Walls wegzuspülen, statt sich allein auf Sprengungen oder manuelles Graben zu verlassen. Der Wert der Idee lag darin, ein großes Hindernis in eine technische Aufgabe zu verwandeln, die Schritt für Schritt gelöst werden konnte.",
  "لكن نجاح الفكرة لم يكن عمل شخص واحد فقط: احتاج التطبيق إلى معدات مناسبة، وتجارب وتقدير للتربة والمياه، وتنظيم فرق العمل، وتحديد مواقع فتح الثغرات وتوقيت تجهيزها. هذه هي الصلة بين الابتكار الفردي والإنجاز الجماعي.": "Der Erfolg war jedoch nicht das Werk einer einzelnen Person. Die Umsetzung erforderte geeignete Geräte, Versuche und eine Einschätzung von Boden und Wasser, die Organisation der Teams sowie die Planung der Stellen und Zeitpunkte für die Durchgänge. Hier zeigt sich, wie eine individuelle Idee und gemeinschaftliche Arbeit zusammenwirken.",
  "المبدأ": "Das Prinzip",
  "تدفق الماء يزيل حبيبات التربة وينقلها بعيدًا عن موضع العمل، فتتكون ثغرة يمكن توسيعها وتجهيزها.": "Das strömende Wasser löst Bodenpartikel und trägt sie vom Arbeitsbereich fort. So entsteht eine Öffnung, die anschließend verbreitert und vorbereitet werden kann.",
  "التحدي العملي": "Die praktische Herausforderung",
  "لا يكفي وجود مضخة؛ يجب ضبط تدفق المياه ومكانها وتنظيم العمل حتى يصبح الممر مناسبًا لعبور القوات والمعدات.": "Eine Pumpe allein reicht nicht aus. Wasserstrom und Einsatzort müssen richtig eingestellt und die Arbeit gut organisiert werden, damit der Durchgang für Truppen und Ausrüstung geeignet ist.",
  "ما وراء الحكاية": "Hinter der Geschichte",
  "العلم ليس معادلة على الورق فقط": "Wissenschaft ist mehr als eine Gleichung auf Papier",
  "تُظهر القصة كيف يمكن لمبدأ فيزيائي معروف أن يصبح حلًا مهمًا عندما يُستخدم في المكان والوقت المناسبين. فالماء الذي نراه عادة وسيلة للشرب أو الري أصبح هنا أداة هندسية لمعالجة عائق عسكري.": "Die Geschichte zeigt, wie ein bekanntes physikalisches Prinzip zu einer wichtigen Lösung werden kann, wenn es zur richtigen Zeit am richtigen Ort eingesetzt wird. Wasser, das wir gewöhnlich zum Trinken oder Bewässern nutzen, wurde hier zu einem technischen Mittel, um ein militärisches Hindernis zu überwinden.",
  "ومن الإنصاف عند رواية الحدث أن نذكر الفكرة المنسوبة إلى باقي زكي يوسف ضمن منظومة أوسع من المهندسين والجنود والمشغلين. فالتاريخ لا ينتقص من صاحب الفكرة حين يوضح أيضًا أن تنفيذها احتاج إلى عمل جماعي.": "Es ist fair, die Baki Zaki Youssef zugeschriebene Idee als Teil eines größeren Zusammenspiels von Ingenieuren, Soldaten und Bedienmannschaften darzustellen. Die Leistung des Ideengebers wird nicht geschmälert, wenn zugleich deutlich wird, dass die Umsetzung Teamarbeit erforderte.",
  "والدرس الذي يمكن نقله إلى حياتنا اليومية هو أن المشكلة الكبيرة قد تُحل عندما نفهم طبيعتها أولًا، ثم نقارن أكثر من حل، ونجرب الحل المناسب، وننظم تنفيذ العمل بدل الاعتماد على القوة وحدها.": "Eine Lehre für unseren Alltag lautet: Ein großes Problem lässt sich oft lösen, wenn wir zuerst seine Ursachen verstehen, mehrere Möglichkeiten vergleichen, eine passende Lösung erproben und die Umsetzung organisieren, statt uns allein auf Kraft zu verlassen.",
  "للاطلاع على صور البطل أحمد إدريس:": "Fotos des Helden Ahmed Idris ansehen:",
  "الهيئة العامة لقصور الثقافة — صاحب الشفرة النوبية": "General Authority of Cultural Palaces – Urheber des nubischen Codes",
  ". لم تُنسخ صورة إلى الموقع لأن ترخيص إعادة استخدامها غير موضح.": ". Es wurde kein Foto auf die Website kopiert, da die Lizenz zur Wiederverwendung nicht eindeutig ist.",
  "من يتحدث لغة لا يعرفها الخصم؟": "Wer spricht eine Sprache, die der Gegner nicht kennt?",
  "مشهد من قرية نوبية على النيل، للتعريف بالبيئة الثقافية لا لتصوير أحمد إدريس أو أحداث الحرب.": "Ansicht eines nubischen Dorfes am Nil zur Darstellung des kulturellen Umfelds; sie zeigt weder Ahmed Idris noch Kriegsgeschehen.",
  "الصورة: Abdelrahman Abdelazeem،": "Foto: Abdelrahman Abdelazeem,",
  "، CC BY-SA 4.0.": ", CC BY-SA 4.0.",
  "تُروى قصة أحمد إدريس، الجندي النوبي المصري، بوصفها مثالًا على استخدام المعرفة اللغوية في الاتصالات العسكرية. ووفق روايات صحفية وشهادات متداولة، اقترح إدريس الاستفادة من اللغة النوبية في نقل بعض الرسائل، لأن الخصم الذي لا يعرف اللغة سيواجه صعوبة أكبر في فهم مضمونها.": "Die Geschichte von Ahmed Idris, einem ägyptischen Soldaten nubischer Herkunft, gilt als Beispiel dafür, wie Sprachkenntnisse in der militärischen Kommunikation eingesetzt werden können. Presseberichten und verbreiteten Zeugenaussagen zufolge schlug Idris vor, für bestimmte Nachrichten die nubische Sprache zu verwenden, weil ein Gegner, der sie nicht versteht, den Inhalt schwerer erfassen könnte.",
  "النوبية ليست لغة واحدة متطابقة في كل مكان؛ بل تضم تنوعات لغوية ومجتمعات لها تاريخ طويل في جنوب مصر وشمال السودان. ومعرفة اللغة في هذه القصة ليست تفصيلًا غريبًا، بل تذكير بأن مهارات الناس وخلفياتهم الثقافية يمكن أن تتحول إلى مورد عملي عند الحاجة.": "Nubisch ist keine überall identische Sprache. Es umfasst verschiedene Sprachformen und Gemeinschaften mit einer langen Geschichte im Süden Ägyptens und im Norden Sudans. Die Sprachkenntnisse in dieser Geschichte sind keine Kuriosität, sondern erinnern daran, dass Fähigkeiten und kulturelle Hintergründe von Menschen bei Bedarf zu einer praktischen Ressource werden können.",
  "ومع ذلك، من المهم وصف القصة بدقة: لا ينبغي اعتبار اللغة وحدها نظام تشفير كاملًا أو ضمانًا للسرية المطلقة. أمن الاتصالات يعتمد على الانضباط وطرق الإرسال وحماية المعلومات، كما أن بعض التفاصيل التاريخية في الروايات الصحفية تحتاج إلى المقارنة بمصادر مستقلة قبل الجزم بها.": "Dennoch muss die Geschichte präzise beschrieben werden: Eine Sprache allein ist weder ein vollständiges Verschlüsselungssystem noch eine Garantie absoluter Geheimhaltung. Sichere Kommunikation hängt auch von Disziplin, Übertragungswegen und dem Schutz von Informationen ab. Einige historische Einzelheiten aus Presseberichten müssen zudem mit unabhängigen Quellen verglichen werden, bevor man sie als gesichert darstellt.",
  "كيف نتحقق من الرواية؟": "Wie überprüfen wir den Bericht?",
  "احترام صاحب القصة واحترام الدليل": "Die Person und die Belege respektieren",
  "حين نقرأ عن أحمد إدريس، يمكننا تقدير قيمة مساهمته والاعتزاز بدور النوبيين المصريين، وفي الوقت نفسه نسأل: ما الذي تؤكده الشهادات؟ وما التفاصيل التي تختلف من مصدر إلى آخر؟ هذا السؤال لا يقلل من القصة؛ بل يجعل عرضها أكثر مسؤولية.": "Wenn wir über Ahmed Idris lesen, können wir seinen Beitrag würdigen und die Rolle der ägyptischen Nubier anerkennen. Gleichzeitig sollten wir fragen: Was bestätigen die Zeugnisse, und welche Einzelheiten unterscheiden sich je nach Quelle? Diese Fragen schmälern die Geschichte nicht, sondern machen ihre Darstellung verantwortungsvoller.",
  "المقارنة بين روايات الصحف، والشهادات المباشرة إن توفرت، والمصادر التاريخية المستقلة تساعد على التمييز بين الفكرة العامة المدعومة وبين التفاصيل التي قد تحتاج إلى توثيق إضافي.": "Der Vergleich von Zeitungsberichten, direkten Zeugenaussagen – sofern verfügbar – und unabhängigen historischen Quellen hilft dabei, die gut belegte Kernaussage von Einzelheiten zu unterscheiden, die noch zusätzliche Belege benötigen.",
  "وتعلّمنا الحكاية أيضًا أن حماية المعلومات لا تعتمد على جهاز أو كلمة سر فقط؛ بل قد تبدأ من المعرفة البشرية، ومن القدرة على التواصل بوضوح مع الفريق الصحيح، ومن إدراك أن التنوع اللغوي والثقافي جزء من قوة المجتمع.": "Die Geschichte lehrt uns außerdem, dass Informationsschutz nicht nur von Geräten oder Passwörtern abhängt. Er kann mit menschlichem Wissen, klarer Kommunikation mit dem richtigen Team und dem Verständnis beginnen, dass sprachliche und kulturelle Vielfalt zur Stärke einer Gesellschaft gehört.",
  "في ظهر السبت 6 أكتوبر 1973، الموافق 10 رمضان 1393 هـ، انطلقت الطائرات المصرية في مهمة جوية كبيرة ضمن خطة الحرب. لم تكن الطائرات تتحرك عشوائيًا؛ لكل مجموعة هدف محدد، ووقت، ومسار، وارتفاع مدروس.": "Am Nachmittag des Samstags, dem 6. Oktober 1973 (10. Ramadan 1393 nach islamischer Zeitrechnung), starteten ägyptische Flugzeuge zu einem großen Luftangriff im Rahmen des Kriegsplans. Sie flogen nicht planlos: Jede Gruppe hatte ein festgelegtes Ziel, einen Zeitpunkt, eine Route und eine geplante Flughöhe.",
  "كانت المهمة أن تضرب مواقع عسكرية مهمة، مثل مراكز القيادة والرادار ومواقع الصواريخ والمطارات، حتى تُربك دفاعات العدو وتساعد القوات المصرية التي تستعد لعبور قناة السويس.": "Der Auftrag bestand darin, wichtige militärische Ziele wie Führungszentren, Radarstellungen, Raketenstellungen und Flugplätze anzugreifen, um die gegnerische Verteidigung zu stören und die ägyptischen Truppen beim geplanten Übergang über den Suezkanal zu unterstützen.",
  "لكن خلف الخريطة والخطة كانت هناك حقيقة إنسانية: داخل كل طائرة طيار له أسرة وأحلام، ويعرف أن العودة ليست مضمونة. بعضهم عاد إلى قاعدته، وبعضهم لم يعد.": "Hinter Karten und Einsatzplänen stand jedoch eine menschliche Wirklichkeit: In jedem Flugzeug saß ein Pilot mit Familie und Hoffnungen, der wusste, dass die Rückkehr nicht sicher war. Einige kehrten zu ihrem Stützpunkt zurück, andere nicht.",
  "حلّقت الطائرات على ارتفاعات منخفضة لتقليل فرصة اكتشافها، ثم اتجهت إلى الأهداف المحددة. كان على الطيار أن يلتزم بالخطة، وينفذ المهمة، ويتعامل مع الخطر في ثوانٍ قليلة.": "Die Flugzeuge flogen in geringer Höhe, um die Wahrscheinlichkeit ihrer Entdeckung zu verringern, und steuerten dann ihre festgelegten Ziele an. Die Piloten mussten sich an den Plan halten, ihren Auftrag erfüllen und innerhalb weniger Sekunden auf Gefahren reagieren.",
  "أعلنت البيانات العسكرية المصرية أن الضربة حققت إصابات مباشرة في أهدافها، وأن معظم الطائرات عادت. لكن الطائرة التي لا تعود ليست رقمًا فقط؛ وراءها إنسان أدّى واجبه حتى النهاية.": "Ägyptische Militärmeldungen erklärten, der Angriff habe seine Ziele direkt getroffen und die meisten Flugzeuge seien zurückgekehrt. Doch ein Flugzeug, das nicht zurückkehrt, ist nicht nur eine Zahl: Dahinter steht ein Mensch, der seine Pflicht bis zum Ende erfüllt hat.",
  "كان عاطف السادات طيارًا مصريًا وشقيق الرئيس أنور السادات. وتذكر روايات منشورة أنه أصرّ على المشاركة في الضربة الأولى، ونفّذ هجومه على هدف عسكري في سيناء، ثم أُصيبت طائرته ولم يعد منها.": "Atef al-Sadat war ein ägyptischer Pilot und der Bruder von Präsident Anwar al-Sadat. Veröffentlichte Berichte besagen, dass er unbedingt am ersten Luftangriff teilnehmen wollte, ein militärisches Ziel im Sinai angriff und anschließend mit seinem beschädigten Flugzeug nicht zurückkehrte.",
  "تختلف بعض الروايات في تفاصيل تسلسل الطلعات وعدد الطائرات والطيارين الذين فقدوا في مراحل اليوم الأول. لذلك لا يصح أن نضع قائمة أسماء أو أرقامًا نهائية من دون سند واضح. الأهم أن نذكر الشهداء باحترام، وأن نتحرّى الدقة في قصصهم.": "Einige Berichte unterscheiden sich hinsichtlich der Reihenfolge der Einsätze und der Zahl der Flugzeuge und Piloten, die im Verlauf des ersten Tages verloren gingen. Deshalb sollten wir keine endgültigen Namenlisten oder Zahlen ohne klare Belege präsentieren. Wichtig ist, der Gefallenen respektvoll zu gedenken und ihre Geschichten sorgfältig zu prüfen.",
  "ملاحظة تاريخية: بعض المصادر تتحدث عن خسائر الضربة الأولى وحدها، وأخرى عن خسائر القتال الجوي خلال اليوم الأول كله؛ لذلك قد تختلف الأعداد باختلاف ما تحسبه كل رواية.": "Historischer Hinweis: Einige Quellen sprechen nur von den Verlusten des ersten Luftangriffs, andere von den Verlusten der gesamten Luftkämpfe am ersten Kriegstag. Die Zahlen können daher je nach Definition variieren.",
  "تحتفظ المصادر المنشورة بصور بعض الأبطال وأسمائهم. نعرض هنا صورتين موثقتين، مع احترام اختلاف الروايات التاريخية وعدم الادعاء بأنهما القائمة الكاملة لكل شهداء الضربة.": "Veröffentlichte Quellen bewahren Fotos und Namen einiger dieser Helden. Hier zeigen wir zwei belegte Beispiele und berücksichtigen dabei unterschiedliche historische Berichte, ohne zu behaupten, dass dies eine vollständige Liste aller Gefallenen des Angriffs sei.",
  "تنبيه للدقة: تختلف بعض المصادر في الرتبة والتفاصيل وترتيب الاستشهاد؛ لذلك نذكر الأسماء دون الجزم بترتيب «أول شهيد»، ولا نعرض هذه الصور على أنها سجل كامل لجميع الشهداء.": "Hinweis zur Genauigkeit: Quellen unterscheiden sich bei Dienstgraden, Einzelheiten und der Reihenfolge der Todesfälle. Deshalb nennen wir die Namen, ohne eine bestimmte Person endgültig als „ersten Gefallenen“ zu bezeichnen, und stellen die Fotos nicht als vollständiges Gedenkregister dar.",
  "لم تُنهِ الضربة الجوية الحرب وحدها، ولم يكن النصر نتيجة سلاح واحد. لقد كانت جزءًا من خطة أكبر شاركت فيها القوات الجوية والمدفعية والجيش والبحرية والدفاع الجوي، ولكل منها مهمة مختلفة.": "Der Luftangriff allein beendete den Krieg nicht, und der Sieg war nicht das Ergebnis einer einzigen Waffengattung. Er war Teil eines größeren Plans, an dem Luftwaffe, Artillerie, Heer, Marine und Luftverteidigung mit jeweils unterschiedlichen Aufgaben beteiligt waren.",
  "ساعد الهجوم الجوي على إرباك بعض مواقع العدو وتقليل قدرتها على الرد في اللحظات الأولى. وبعده بدأ التمهيد المدفعي وعبرت مجموعات من الجنود قناة السويس، في واحدة من أهم مراحل الحرب.": "Der Luftangriff trug dazu bei, einige gegnerische Stellungen zu stören und ihre Reaktionsfähigkeit in den ersten Momenten einzuschränken. Danach begann die Artillerievorbereitung, und Gruppen ägyptischer Soldaten überquerten den Suezkanal – eine der wichtigsten Phasen des Krieges.",
  "حين نتذكر شهداء الضربة الجوية الأولى، لا نتذكر الطائرات والأهداف فقط. نتذكر أشخاصًا حملوا مسؤولية صعبة في لحظة مصيرية، ونتذكر أسرًا انتظرت عودتهم ولم ترهم مرة أخرى.": "Wenn wir der Gefallenen des ersten Luftangriffs gedenken, erinnern wir uns nicht nur an Flugzeuge und Ziele. Wir erinnern uns an Menschen, die in einem entscheidenden Augenblick eine schwere Verantwortung trugen, und an Familien, die auf ihre Rückkehr warteten und sie nie wiedersahen.",
  "كتبت هذه الحكاية لأتعلّم أن التاريخ ليس تواريخ محفوظة فحسب؛ إنه قرارات بشرية وتضحيات حقيقية، وأن أفضل طريقة لتكريم أصحابها هي أن نعرف قصصهم بأمانة ونحفظ ذكراهم.": "Diese Geschichte soll uns zeigen, dass Geschichte nicht nur aus auswendig gelernten Daten besteht. Sie handelt von menschlichen Entscheidungen und wirklichen Opfern. Am besten ehren wir diese Menschen, indem wir ihre Geschichten wahrheitsgetreu erzählen und ihr Andenken bewahren.",
  "تتطلب الضربة الجوية المنسقة أكثر من طائرات تتحرك في الوقت نفسه. فقبل الإقلاع تُحدد الأهداف والمسارات والارتفاعات والتوقيت، وتحتاج كل مجموعة إلى معرفة مهمتها وما يتصل بها من مهام مجموعات أخرى. كما أن المفاجأة تعتمد على التخطيط والانضباط بقدر اعتمادها على السرعة.": "Ein koordinierter Luftangriff erfordert mehr als Flugzeuge, die gleichzeitig starten. Vor dem Abflug werden Ziele, Routen, Flughöhen und Zeitpunkte festgelegt. Jede Gruppe muss ihren Auftrag und dessen Verbindung zu den Aufgaben anderer Gruppen kennen. Der Überraschungseffekt hängt ebenso von Planung und Disziplin wie von Geschwindigkeit ab.",
  "كان الهدف العام للضربة الأولى دعم خطة العبور بإرباك مراكز القيادة والسيطرة وبعض المواقع العسكرية، لكن لا يصح اختزال الحرب كلها في دقائق الضربة الأولى. فالنتائج التي تلتها ارتبطت بعمل القوات البرية والدفاع الجوي والمدفعية والبحرية وبالتطورات التي وقعت خلال الأيام التالية.": "Das allgemeine Ziel des ersten Angriffs war es, den Übergangsplan zu unterstützen, indem Führungszentren und bestimmte militärische Stellungen gestört wurden. Der gesamte Krieg lässt sich jedoch nicht auf die wenigen Minuten dieses Angriffs reduzieren. Die weiteren Ergebnisse hingen auch vom Einsatz der Bodentruppen, der Luftverteidigung, der Artillerie und der Marine sowie von den Entwicklungen der folgenden Tage ab.",
  "وعند قراءة الأرقام المتداولة عن عدد الطائرات أو الأهداف، يجب الانتباه إلى مصدر الرقم وما إذا كان يصف الخطة المعلنة أم التنفيذ الفعلي. قد تختلف الروايات في بعض التفاصيل، لذلك يُذكر الرقم مع نسبته إلى مصدره بدل تقديمه كحقيقة منفصلة عن سياقها.": "Bei Zahlen zur Anzahl der Flugzeuge oder Ziele sollte man darauf achten, aus welcher Quelle sie stammen und ob sie den angekündigten Plan oder die tatsächliche Durchführung beschreiben. Berichte können sich in Einzelheiten unterscheiden. Deshalb sollte jede Zahl mit ihrer Quelle genannt und nicht aus ihrem Zusammenhang gelöst werden.",
  "عندما نقرأ أسماء الطيارين الذين استشهدوا، لا ينبغي أن نراهم مجرد قائمة في نهاية الحكاية. كان لكل واحد منهم تدريب طويل وأسرة وأصدقاء ومسار حياة، ثم وجد نفسه أمام مهمة عسكرية تنطوي على مخاطر حقيقية.": "Wenn wir die Namen der gefallenen Piloten lesen, sollten wir sie nicht nur als Liste am Ende einer Geschichte betrachten. Jeder von ihnen hatte eine lange Ausbildung, eine Familie, Freunde und einen eigenen Lebensweg – und stand schließlich vor einem Militäreinsatz mit realen Gefahren.",
  "وتساعدنا قصة النقيب طيار عاطف السادات على تذكّر أن الشجاعة ليست غياب الخوف، بل أداء الواجب في ظروف صعبة. وفي الوقت نفسه، يجب التحقق من تفاصيل كل مهمة ومن الروايات المتداولة عنها، خصوصًا عندما تختلف المصادر في وصف ما جرى لحظة بلحظة.": "Die Geschichte des Hauptmanns und Piloten Atef al-Sadat erinnert uns daran, dass Mut nicht bedeutet, keine Angst zu haben, sondern unter schwierigen Bedingungen seine Pflicht zu erfüllen. Zugleich müssen die Einzelheiten jedes Einsatzes und die darüber verbreiteten Berichte überprüft werden, besonders wenn Quellen den Ablauf unterschiedlich schildern.",
  "الدرس الأوسع أن الإنجاز العسكري لا يصنعه فرد واحد وحده؛ بل يستند إلى تدريب وتخطيط واتصالات ودعم فني وتنسيق بين وحدات متعددة.": "Die übergeordnete Lehre lautet: Militärische Leistungen werden nicht von einer einzelnen Person allein erbracht. Sie beruhen auf Ausbildung, Planung, Kommunikation, technischer Unterstützung und der Koordination vieler Einheiten.",
  "أُعيدت صياغة المعلومات لتناسب المرحلة العمرية، مع التمييز بين ما تثبته المصادر وما تختلف حوله الروايات.": "Die Informationen wurden altersgerecht neu formuliert. Dabei wird zwischen belegten Tatsachen und Punkten unterschieden, über die Berichte voneinander abweichen.",
  "وأنا أبحث عن العلماء الذين تركوا أثرًا كبيرًا في التاريخ، لفت انتباهي عالم عاش منذ أكثر من ألف عام، واستطاع أن يجمع بين حب المعرفة والطب والفلسفة. إنه ابن سينا، الذي عُرف بلقب «الشيخ الرئيس».": "Bei meiner Suche nach Wissenschaftlern, die Geschichte nachhaltig geprägt haben, fiel mir ein Gelehrter auf, der vor mehr als tausend Jahren lebte und Wissensdurst, Medizin und Philosophie miteinander verband: Ibn Sina, bekannt als „der Meister und Fürst der Gelehrten“.",
  "وُلد ابن سينا، واسمه أبو علي الحسين بن عبد الله بن سينا، نحو عام 980 ميلاديًا في منطقة بخارى، الواقعة في أوزبكستان حاليًا. اهتم منذ صغره بالتعلم، ودرس القرآن واللغة والفلسفة والعلوم، ثم اتجه إلى الطب حتى أصبح طبيبًا معروفًا في عصره.": "Ibn Sina, mit vollem Namen Abu Ali al-Husain ibn Abdullah ibn Sina, wurde um 980 in der Region Buchara geboren, die heute zu Usbekistan gehört. Schon früh interessierte er sich für das Lernen. Er studierte den Koran, Sprache, Philosophie und Wissenschaften und wandte sich später der Medizin zu, in der er zu einem bekannten Arzt seiner Zeit wurde.",
  "لم يكن أثر ابن سينا في الطب وحده؛ فقد ألّف كتبًا في الفلسفة والمنطق وموضوعات أخرى. ومن أشهر مؤلفاته كتاب «القانون في الطب»، الذي نظّم فيه معارف طبية من عصره وأضاف إليها ما توصل إليه من دراسة وخبرة.": "Ibn Sinas Einfluss beschränkte sich nicht auf die Medizin. Er verfasste auch Werke über Philosophie, Logik und weitere Themen. Zu seinen bekanntesten Büchern gehört der „Kanon der Medizin“, in dem er das medizinische Wissen seiner Zeit ordnete und Erkenntnisse aus seinem Studium und seiner Erfahrung ergänzte.",
  "انتقل تأثير الكتاب إلى أوروبا بعد ترجمته إلى اللاتينية في القرن الثاني عشر، وأصبح مرجعًا مهمًا في التعليم الطبي لقرون طويلة. وهكذا تجاوز أثر ابن سينا حدود المكان الذي عاش فيه، ووصلت أفكاره إلى أجيال من الدارسين في مناطق مختلفة من العالم.": "Nachdem das Buch im 12. Jahrhundert ins Lateinische übersetzt worden war, verbreitete sich sein Einfluss auch in Europa. Es wurde über viele Jahrhunderte zu einem wichtigen Werk der medizinischen Ausbildung. So reichte Ibn Sinas Wirkung weit über seine eigene Lebenswelt hinaus und prägte Lernende in verschiedenen Teilen der Welt.",
  "توفي ابن سينا عام 1037 ميلاديًا، لكن كتبه بقيت شاهدًا على رحلة عقل أحب المعرفة وسعى إلى فهم الإنسان والعالم من حوله.": "Ibn Sina starb im Jahr 1037. Seine Bücher zeugen bis heute von einem Geist, der Wissen liebte und den Menschen sowie die Welt um ihn herum verstehen wollte.",
  "تذكّرني حكاية ابن سينا بأن حب التعلم لا يقتصر على مادة واحدة؛ فقد يفتح لنا بابًا إلى علوم كثيرة، ويجعل أثرنا ممتدًا إلى أجيال لم نلتقِ بها قط.": "Ibn Sinas Geschichte erinnert mich daran, dass Lernfreude nicht auf ein einziges Fach beschränkt sein muss. Sie kann Türen zu vielen Wissenschaften öffnen und unseren Einfluss bis zu Generationen tragen, denen wir niemals begegnen werden.",
  "لا توجد صورة فوتوغرافية لابن سينا؛ فقد عاش في القرن العاشر الميلادي، قبل اختراع التصوير بقرون طويلة. لذلك ينبغي التعامل مع الصور المتداولة له باعتبارها رسومًا أو صورًا فنية أُنتجت في عصور لاحقة، لا ملامح مؤكدة لوجهه.": "Es gibt keine Fotografie von Ibn Sina: Er lebte im 10. Jahrhundert, viele Jahrhunderte vor der Erfindung der Fotografie. Verbreitete Darstellungen von ihm sind daher spätere Zeichnungen oder Kunstwerke und keine gesicherten Abbildungen seines tatsächlichen Gesichts.",
  "عاش ابن سينا في عالم كانت فيه الكتب والنسخ اليدوي ومجالس العلماء وطرق السفر بين المدن وسائل أساسية لانتقال المعرفة. وكانت حياة العالم تعتمد على القراءة والمناقشة والملاحظة، وعلى الوصول إلى الكتب والمعلمين والرعاية التي تتيح له متابعة البحث.": "Ibn Sina lebte in einer Welt, in der Bücher, handschriftliche Abschriften, Gelehrtenkreise und Reisen zwischen Städten wichtige Wege zur Verbreitung von Wissen waren. Das Leben eines Gelehrten hing von Lesen, Diskussion und Beobachtung sowie vom Zugang zu Büchern, Lehrern und Unterstützung für seine Forschung ab.",
  "جمع كتاب «القانون في الطب» معارف طبية كانت معروفة في عصر ابن سينا، ونظمها في أبواب تساعد على دراستها والرجوع إليها. وتناول الكتاب موضوعات مثل وصف الأمراض، وملاحظة الأعراض، والأدوية، وأجزاء الجسم، وطرق التفكير في التشخيص والعلاج وفق المعرفة المتاحة آنذاك.": "Der „Kanon der Medizin“ sammelte medizinische Kenntnisse, die zu Ibn Sinas Zeit bekannt waren, und ordnete sie in Abschnitte, die das Lernen und Nachschlagen erleichterten. Das Werk behandelte unter anderem Krankheiten, Symptome, Arzneimittel, Körperteile sowie damalige Ansätze zur Diagnose und Behandlung.",
  "لكن أهمية الكتاب التاريخية لا تعني أن كل وصفة أو نظرية وردت فيه تصلح للطب الحديث. فالعلم يتغير عندما تظهر أدوات قياس وتجارب وأدلة جديدة؛ لذلك ندرس كتب الطب القديمة لفهم تاريخ المعرفة، ولا نستخدمها بديلًا عن النصيحة الطبية الحديثة المبنية على الأدلة.": "Die historische Bedeutung des Buches bedeutet jedoch nicht, dass jedes darin beschriebene Heilmittel oder jede Theorie für die moderne Medizin geeignet ist. Wissenschaft verändert sich durch neue Messinstrumente, Experimente und Belege. Alte medizinische Werke helfen uns, die Geschichte des Wissens zu verstehen, ersetzen aber keine evidenzbasierte moderne medizinische Beratung.",
  "كما أن ابن سينا لم يكن طبيبًا فقط؛ فقد كتب في المنطق والفلسفة والطبيعة، وهو ما يعكس اتساع اهتمام بعض العلماء في عصره بمجالات متعددة. ومع ذلك، من الأفضل أن ننسب إليه الأعمال والأفكار الموثقة بدل إطلاق أوصاف مطلقة لا يمكن اختبارها.": "Ibn Sina war nicht nur Arzt. Er schrieb auch über Logik, Philosophie und Naturkunde, was das breite Interesse mancher Gelehrter seiner Zeit an verschiedenen Fachgebieten zeigt. Dennoch sollten wir ihm belegte Werke und Ideen zuschreiben, statt absolute Behauptungen aufzustellen, die sich nicht überprüfen lassen.",
  "ملاحظة تحريرية: حُذفت مبالغات من النص الأصلي مثل «دكتاتور الطب»، وادعاء أن أساتذته كانوا يتعلمون منه، والقول إنه كان يحفظ الأمراض وعلاجاتها كلها عن ظهر قلب. لم نثبت عمرًا محددًا لحفظ القرآن. الرسوم توضيحية وليست صورًا أرشيفية أو صورة شخصية لابن سينا.": "Redaktioneller Hinweis: Übertreibungen aus dem ursprünglichen Text wurden entfernt, darunter die Bezeichnung „Diktator der Medizin“, die Behauptung, seine Lehrer hätten von ihm gelernt, und die Aussage, er habe alle Krankheiten und ihre Behandlungen auswendig gekannt. Ein bestimmtes Alter, in dem er den Koran auswendig gelernt haben soll, wurde nicht bestätigt. Die Abbildungen sind Illustrationen, keine Archivfotos oder gesicherten Porträts Ibn Sinas.",
  "وُلد أحمد عرابي سنة 1841 في قرية هرية رزنة بمحافظة الشرقية. التحق بالجيش المصري في عهد محمد سعيد باشا، وتدرّج في الخدمة العسكرية. وفي زمنه، كان التمييز داخل الجيش بين الضباط المصريين وغيرهم أحد أسباب التوتر والغضب بين قطاعات من الضباط.": "Ahmed Urabi wurde 1841 im Dorf Hirriyet Razna im Gouvernement Scharqiyya geboren. Er trat während der Herrschaft von Muhammad Said Pascha in die ägyptische Armee ein und stieg im Militärdienst auf. Zu seiner Zeit gehörte die unterschiedliche Behandlung ägyptischer und anderer Offiziere zu den Ursachen von Spannungen und Unzufriedenheit unter Teilen des Offizierskorps.",
  "لم تكن الحركة العرابية حدثًا مفاجئًا بلا مقدمات؛ فقد تراكمت مطالب تتعلق بالترقيات والتمثيل والإنفاق على الجيش، إلى جانب أزمة مالية وسياسية أثّرت في حكم مصر.": "Die Urabi-Bewegung kam nicht ohne Vorzeichen. Forderungen nach Beförderungen, politischer Vertretung und höheren Ausgaben für die Armee hatten sich aufgestaut, während zugleich eine Finanz- und politische Krise die Regierung Ägyptens belastete.",
  "ارتبط اسم عرابي بوقوفه أمام الخديوي توفيق في ميدان عابدين يوم 9 سبتمبر 1881، حين عرض الضباط والجموع مطالبهم. اشتهرت في الذاكرة المصرية عبارة «لقد خلقنا الله أحرارًا ولم يخلقنا تراثًا أو عقارًا»، لكن تفاصيل الصياغة الحرفية تختلف بين الروايات؛ لذلك نذكرها باعتبارها العبارة الأشهر المنسوبة إلى ذلك الموقف، لا محضرًا حرفيًا متفقًا عليه.": "Urabis Name ist mit seinem Auftreten vor Khedive Tawfiq auf dem Abdin-Platz am 9. September 1881 verbunden, als Offiziere und Menschenmenge ihre Forderungen vorbrachten. Im ägyptischen Gedächtnis ist der Satz „Gott hat uns frei erschaffen, nicht als Erbe oder Besitz“ berühmt. Die genaue Formulierung unterscheidet sich jedoch zwischen den Berichten; deshalb führen wir ihn als die bekannteste Aussage an, die diesem Ereignis zugeschrieben wird, nicht als wörtlich gesichertes Protokoll.",
  "تصاعد التوتر إلى مواجهة عسكرية، وانتهت معركة التل الكبير في سبتمبر 1882 بانتصار القوات البريطانية ودخولها القاهرة، لتبدأ مرحلة الاحتلال البريطاني.": "Die Spannungen eskalierten zu einer militärischen Konfrontation. Die Schlacht von Tel el-Kebir endete im September 1882 mit einem britischen Sieg und dem Einmarsch britischer Truppen in Kairo; damit begann die Phase der britischen Besatzung.",
  "تحتاج هذه المرحلة إلى قراءة متوازنة: فقد جمعت الحركة العرابية بين مطالب إصلاحية ومصالح سياسية وعسكرية متشابكة، كما اختلف المؤرخون في تقييم قيادتها ونتائجها.": "Diese Phase muss ausgewogen betrachtet werden: Die Urabi-Bewegung verband Reformforderungen mit miteinander verflochtenen politischen und militärischen Interessen. Historiker bewerten ihre Führung und Folgen unterschiedlich.",
  "تساعدنا حكاية عرابي على فهم أن الأحداث الكبيرة تنشأ من ظروف اجتماعية واقتصادية وسياسية متشابكة. كما تذكّرنا بأهمية التمييز بين الوقائع الثابتة والعبارات التي اشتهرت في الذاكرة الشعبية، وبين وصف الحدث والحكم عليه.": "Urabis Geschichte hilft uns zu verstehen, dass große Ereignisse aus verflochtenen sozialen, wirtschaftlichen und politischen Umständen entstehen. Sie erinnert uns auch daran, belegte Tatsachen von überlieferten Redewendungen sowie die Beschreibung eines Ereignisses von seiner Bewertung zu unterscheiden.",
  "اسم «الثورة العرابية» يُستخدم لوصف حركة 1879–1882، بينما يُشار إلى مظاهرة عابدين في 9 سبتمبر 1881 بوصفها واحدة من أبرز لحظاتها.": "Der Begriff „Urabi-Revolution“ bezeichnet die Bewegung von 1879 bis 1882. Die Demonstration auf dem Abdin-Platz am 9. September 1881 gilt als einer ihrer wichtigsten Momente.",
  "تساعدنا الصورة على ربط الحكاية بشخصية تاريخية حقيقية، لكن الصورة وحدها لا تشرح أسباب الحركة العرابية ولا تكفي للحكم على نتائجها. لفهم عرابي، نحتاج إلى النظر إلى الجيش والإدارة والديون والتدخل الأوروبي والصراع بين الخديوي والضباط وأصحاب المطالب الإصلاحية.": "Das Bild verbindet die Geschichte mit einer realen historischen Persönlichkeit, erklärt aber allein weder die Ursachen der Urabi-Bewegung noch ihre Folgen. Um Urabi zu verstehen, müssen wir Armee, Verwaltung, Schulden, europäische Einmischung und den Konflikt zwischen dem Khedive, den Offizieren und den Reformbefürwortern betrachten.",
  "تداخلت في أواخر القرن التاسع عشر عدة أزمات: شكاوى داخل الجيش من التمييز في الترقيات، ومطالب بمشاركة أوسع في الحكم، وضغط مالي على الدولة، ونفوذ أوروبي متزايد. لذلك لا يمكن تفسير الحركة بسبب واحد أو اعتبارها مجرد خلاف بين ضابط وحاكم.": "Im späten 19. Jahrhundert überschnitten sich mehrere Krisen: Beschwerden über ungleiche Beförderungen in der Armee, Forderungen nach größerer politischer Mitbestimmung, finanzieller Druck auf den Staat und zunehmender europäischer Einfluss. Die Bewegung lässt sich deshalb weder auf eine einzige Ursache noch auf einen bloßen Streit zwischen einem Offizier und einem Herrscher reduzieren.",
  "بعد مظاهرة عابدين عام 1881، تصاعد الصراع السياسي والعسكري. وفي عام 1882 تدخلت بريطانيا عسكريًا، وانتهت المواجهة بمعركة التل الكبير ثم احتلال القاهرة. وأُسر عرابي ونُفي إلى سيلان، التي تُعرف اليوم بسريلانكا، قبل أن يعود إلى مصر بعد سنوات.": "Nach der Demonstration auf dem Abdin-Platz im Jahr 1881 verschärfte sich der politische und militärische Konflikt. 1882 griff Großbritannien militärisch ein; die Auseinandersetzung endete mit der Schlacht von Tel el-Kebir und der Besetzung Kairos. Urabi wurde gefangen genommen und nach Ceylon, dem heutigen Sri Lanka, verbannt, bevor er Jahre später nach Ägypten zurückkehrte.",
  "اختلف المؤرخون في تقييم الحركة: فهناك من يركز على مطالبها الوطنية والإصلاحية، ومن يدرس أخطاء قيادتها والظروف التي أدت إلى الهزيمة. والقراءة التاريخية الجيدة لا تتجاهل أيًا من الجانبين، بل تفصل بين الوقائع المؤكدة والتفسيرات والأحكام.": "Historiker bewerten die Bewegung unterschiedlich. Einige betonen ihre nationalen und reformorientierten Forderungen, andere untersuchen Fehler ihrer Führung und die Umstände der Niederlage. Eine gute historische Betrachtung ignoriert keine dieser Seiten, sondern trennt gesicherte Tatsachen von Interpretationen und Werturteilen.",
  "وعندما نسمع العبارة الشهيرة المنسوبة إلى عرابي «لقد خلقنا الله أحرارًا»، يجدر بنا تذكر أن شهرة العبارة لا تعني أن كل صياغة متداولة لها محضر حرفي متفق عليه؛ لذلك تعرض الحكاية العبارة بوصفها من أشهر ما نُسب إلى موقف عابدين، مع الإشارة إلى اختلاف الروايات.": "Wenn wir den Urabi zugeschriebenen berühmten Satz „Gott hat uns frei erschaffen“ hören, sollten wir bedenken, dass seine Bekanntheit keine einheitlich überlieferte wörtliche Mitschrift garantiert. Die Geschichte stellt ihn daher als eine der bekanntesten Aussagen zum Ereignis auf dem Abdin-Platz dar und weist auf abweichende Überlieferungen hin.",
  "النص تعليمي مبسط؛ بعض الأقوال المشهورة منقولة بوصفها روايات منسوبة، مع التنبيه إلى اختلاف التفاصيل بين المصادر.": "Der Text ist eine vereinfachte Bildungsdarstellung. Einige bekannte Aussagen werden als überlieferte Zuschreibungen wiedergegeben, wobei auf Unterschiede zwischen den Quellen hingewiesen wird.",
  "أحمد زويل عالم مصري عظيم، اتولد في مدينة دمنهور سنة 1946، وكان بيحب العلم من وهو صغير. اجتهد في دراسته لحد ما سافر أمريكا، ونجح في أبحاثه العلمية، ورفع اسم مصر والعرب في العالم كله.": "Ahmed Zewail war ein bedeutender ägyptischer Wissenschaftler. Er wurde 1946 in Damanhur geboren und interessierte sich schon früh für Wissenschaft. Er lernte fleißig, ging später in die USA und erzielte mit seiner Forschung große Erfolge, durch die er Ägypten und die arabische Welt international bekannt machte.",
  "وُلد أحمد حسن زويل يوم 26 فبراير 1946 في مدينة دمنهور بمصر. درس الكيمياء في جامعة الإسكندرية، ثم سافر إلى الولايات المتحدة ونال الدكتوراه من جامعة بنسلفانيا. وبعد فترة عمل في جامعة كاليفورنيا ببركلي، انتقل سنة 1976 إلى معهد كاليفورنيا للتكنولوجيا (كالتك) في مدينة باسادينا.": "Ahmed Hassan Zewail wurde am 26. Februar 1946 in Damanhur in Ägypten geboren. Er studierte Chemie an der Universität Alexandria, ging anschließend in die Vereinigten Staaten und promovierte an der University of Pennsylvania. Nach einer Tätigkeit an der University of California, Berkeley, wechselte er 1976 zum California Institute of Technology (Caltech) in Pasadena.",
  "في التفاعل الكيميائي تتحرك الذرات داخل الجزيئات وتتغير أماكنها حتى تتكوّن مواد جديدة. والذرات داخل الجزيء تهتز، والزمن بين اهتزازة وأخرى قصير جدًا: بين 10 و100 فيمتو ثانية. والفيمتو ثانية جزء من مليون مليار جزء من الثانية الواحدة. ولفترة طويلة كان العلماء في الغالب يستنتجون ما يحدث بين بداية التفاعل ونهايته دون أن يروه.": "Bei einer chemischen Reaktion bewegen sich Atome innerhalb von Molekülen und ordnen sich neu an, bis neue Stoffe entstehen. Die Atome schwingen; zwischen zwei Schwingungen liegen oft nur 10 bis 100 Femtosekunden. Eine Femtosekunde ist ein billiardstel einer Sekunde. Lange Zeit konnten Wissenschaftler die Vorgänge zwischen Beginn und Ende einer Reaktion meist nur erschließen, nicht direkt beobachten.",
  "رسم توضيحي لمقياس الزمن: كل خطوة أصغر ألف مرة من التي قبلها، حتى نصل إلى الفيمتو ثانية (واحد على مليون مليار من الثانية).": "Schaubild zur Zeitskala: Jeder Schritt ist tausendmal kürzer als der vorherige, bis zur Femtosekunde – einem Billiardstel einer Sekunde.",
  "في أواخر الثمانينيات طوّر زويل طرقًا لدراسة التفاعلات الكيميائية بتفصيل، باستخدام نبضات ليزر شديدة القِصر. وبفضلها استطاع العلماء لأول مرة أن يلاحظوا الذرات وهي تتحرك أثناء التفاعل، كأن الحدث يجري بالحركة البطيئة. وسُمّي هذا المجال «كيمياء الفيمتو».": "In den späten 1980er-Jahren entwickelte Zewail Methoden, um chemische Reaktionen mithilfe extrem kurzer Laserpulse detailliert zu untersuchen. Damit konnten Wissenschaftler erstmals Atombewegungen während einer Reaktion verfolgen – als liefe das Geschehen in Zeitlupe. Dieses Forschungsgebiet wurde als Femtochemie bekannt.",
  "وفي 12 أكتوبر 1999 أعلنت الأكاديمية الملكية السويدية للعلوم فوز زويل بجائزة نوبل في الكيمياء لدراساته عن حالات الانتقال في التفاعلات الكيميائية باستخدام مطيافية الفيمتو ثانية. وكان أول مصري وأول عربي يفوز بجائزة نوبل في مجال علمي.": "Am 12. Oktober 1999 gab die Königlich Schwedische Akademie der Wissenschaften bekannt, dass Zewail den Nobelpreis für Chemie für seine Untersuchungen der Übergangszustände chemischer Reaktionen mithilfe der Femtosekundenspektroskopie erhalten sollte. Er war der erste Ägypter und der erste Araber, der einen naturwissenschaftlichen Nobelpreis gewann.",
  "توفي زويل يوم 2 أغسطس 2016 في باسادينا بولاية كاليفورنيا. وكان أيضًا رئيسًا لمجلس أمناء مدينة زويل للعلوم والتكنولوجيا في القاهرة.": "Zewail starb am 2. August 2016 in Pasadena, Kalifornien. Außerdem war er Vorsitzender des Kuratoriums der Zewail City of Science and Technology in Kairo.",
  "تخرج زويل في كلية العلوم بجامعة الإسكندرية سنة 1967 بتقدير امتياز مع مرتبة الشرف في الكيمياء، وعمل فيها معيدًا قبل سفره إلى أمريكا. وفي سنة 2010 أُطلق اسمه على مدرج في الكلية.": "Zewail schloss 1967 sein Chemiestudium an der Fakultät für Naturwissenschaften der Universität Alexandria mit Auszeichnung ab und arbeitete dort als wissenschaftlicher Assistent, bevor er in die USA ging. 2010 wurde ein Hörsaal der Fakultät nach ihm benannt.",
  "وبعد نوبل شارك سنة 2009 في المجلس الاستشاري للرئيس الأمريكي للعلوم والتكنولوجيا، وكان أول مبعوث علمي أمريكي إلى الشرق الأوسط. واستُخدمت مطيافية الفيمتو ثانية بعده في دراسة التحفيز والمواد والإلكترونيات.": "Nach seinem Nobelpreis gehörte er 2009 dem Beratergremium des US-Präsidenten für Wissenschaft und Technologie an und wurde der erste US-amerikanische Wissenschaftsgesandte für den Nahen Osten. Die Femtosekundenspektroskopie wurde später unter anderem zur Erforschung von Katalyse, Materialien und Elektronik eingesetzt.",
  "وارتبط زويل بمكتبة الإسكندرية أيضًا: كان عضوًا في مجلسها الاستشاري، وأتاحت المكتبة لزوارها الاطلاع على نسخة من شهادة جائزته في قسم نوبل. وبعد وفاته أهدت زوجته مكتبته الخاصة إلى مكتبة الإسكندرية، باستثناء كتب العلوم البحتة التي ذهبت إلى جامعة زويل تنفيذًا لوصيته.": "Zewail war auch mit der Bibliotheca Alexandrina verbunden: Er gehörte ihrem Beirat an, und die Bibliothek zeigte Besuchern eine Kopie seiner Nobelpreisurkunde in ihrer Nobel-Abteilung. Nach seinem Tod schenkte seine Frau seine persönliche Bibliothek der Bibliotheca Alexandrina. Bücher aus den reinen Naturwissenschaften gingen gemäß seinem Wunsch an die Zewail University.",
  "حكاية أحمد زويل بتعلّمنا إن النجاح محتاج صبر واجتهاد وإيمان بالحلم، وإن الطالب الصغير ممكن يكبر ويصبح عالمًا عظيمًا يخدم بلده والإنسانية كلها.": "Ahmed Zewails Geschichte lehrt uns, dass Erfolg Geduld, Fleiß und Vertrauen in den eigenen Traum erfordert. Auch ein junger Schüler kann zu einem bedeutenden Wissenschaftler heranwachsen und seinem Land sowie der ganzen Menschheit dienen.",
  "الرسوم الموجودة في مقدمة الحكاية تشرح فكرة حركة الذرات، لكنها ليست صورًا فوتوغرافية لتجربة زويل. أما الصورة أعلاه فهي صورة حقيقية للعالم نفسه، ويجب التمييز دائمًا بين الصورة التاريخية والرسمة التي تشرح مفهومًا علميًا.": "Die Zeichnungen am Anfang der Geschichte veranschaulichen die Bewegung von Atomen; sie sind keine Fotografien eines Experiments von Zewail. Das Foto oben zeigt dagegen den Wissenschaftler selbst. Historische Fotografien und erklärende wissenschaftliche Illustrationen sollten stets auseinandergehalten werden.",
  "قبل تطور تقنيات الفيمتو ثانية، كان العلماء يستطيعون دراسة المواد قبل التفاعل وبعده، لكن بعض الخطوات الوسيطة تحدث بسرعة شديدة بحيث يصعب رصدها بالوسائل التقليدية. طوّر زويل طرقًا تعتمد على نبضات ليزر فائقة القصر، لتعمل كأنها ومضات متتابعة تكشف مراحل التفاعل.": "Vor der Entwicklung der Femtosekundentechnik konnten Wissenschaftler Stoffe vor und nach einer Reaktion untersuchen. Einige Zwischenschritte liefen jedoch so schnell ab, dass sie mit herkömmlichen Methoden schwer zu erfassen waren. Zewail entwickelte Verfahren mit ultrakurzen Laserpulsen, die wie aufeinanderfolgende Lichtblitze verschiedene Reaktionsphasen sichtbar machten.",
  "الفيمتو ثانية تساوي 10⁻¹⁵ من الثانية، أي جزءًا من مليون مليار جزء من الثانية. هذه المدة قصيرة للغاية، لكنها مهمة لأن اهتزاز الذرات داخل الجزيئات قد يحدث في نطاق عشرات الفيمتو ثانية. ومن خلال ضبط توقيت النبضات وقياس الإشارات الناتجة، يستطيع الباحثون بناء صورة عن تغير الجزيئات أثناء التفاعل.": "Eine Femtosekunde entspricht 10⁻¹⁵ Sekunden, also einem Billiardstel einer Sekunde. Diese Zeitspanne ist extrem kurz, aber wichtig, weil Atome in Molekülen innerhalb von einigen Dutzend Femtosekunden schwingen können. Durch präzise abgestimmte Laserpulse und die Messung der entstehenden Signale können Forschende nachvollziehen, wie sich Moleküle während einer Reaktion verändern.",
  "لا تعني هذه التقنية أن العلماء يصورون الذرات بكاميرا عادية كما نصوّر الأشخاص؛ بل إنهم يستخدمون قياسات ضوئية وتجارب دقيقة، ثم يحللون النتائج لفهم ما يحدث. هذا الفرق مهم حتى لا تتحول الاستعارة المفيدة — «كاميرا سريعة جدًا» — إلى وصف حرفي مضلل.": "Diese Technik bedeutet nicht, dass Wissenschaftler Atome mit einer gewöhnlichen Kamera wie Menschen fotografieren. Sie führen präzise optische Messungen und Experimente durch und analysieren anschließend die Ergebnisse. Diese Unterscheidung ist wichtig, damit das hilfreiche Bild einer „extrem schnellen Kamera“ nicht irrtümlich wörtlich verstanden wird.",
  "كان حصول زويل على جائزة نوبل في الكيمياء عام 1999 اعترافًا بأهمية هذا المجال، لكنه لم يكن نهاية البحث. فقد واصل العلماء تطوير أدوات أقصر زمنًا وطرقًا جديدة لدراسة المواد والتفاعلات، مستفيدين من الأساس الذي ساعدت كيمياء الفيمتو على ترسيخه.": "Zewails Nobelpreis für Chemie im Jahr 1999 würdigte die Bedeutung dieses Forschungsgebiets, bedeutete aber nicht das Ende der Entwicklung. Wissenschaftler verbesserten weiterhin zeitlich noch präzisere Instrumente und neue Methoden zur Untersuchung von Stoffen und Reaktionen und bauten dabei auf den Grundlagen der Femtochemie auf.",
  ": عمله في المجلس الاستشاري للرئيس الأمريكي منذ 2009 ومبعوثًا علميًا، واستخدامات مطيافية الفيمتو ثانية.": ": Seine Tätigkeit im wissenschaftlichen Beirat des US-Präsidenten ab 2009 und als Wissenschaftsgesandter sowie Anwendungen der Femtosekundenspektroskopie.",
  "ملاحظة تحريرية: جملة «كان بيحب العلم من وهو صغير» من كلام الراوية، ولم نجد لها مصدرًا مباشرًا في المراجع المذكورة. اختُصرت بداية الراوية لأن تفاصيل الفيمتو ثانية ونوبل شُرحت لاحقًا بدقة أكبر، والنص الأصلي محفوظ كاملًا. تختلف المصادر في مكان نشأته (الإسكندرية في موقع نوبل ودسوق في مصادر أخرى)، فلم نذكره. معلومات مكتبة الإسكندرية في قسم «من الإسكندرية إلى العالم» مصدرها صحف مصرية وليس موقع المكتبة نفسه. الرسوم توضيحية وليست صورًا علمية أو أرشيفية.": "Redaktioneller Hinweis: Der Satz „Er liebte Wissenschaft schon als Kind“ stammt aus der Erzählung; in den genannten Referenzen fanden wir dafür keinen direkten Beleg. Der erzählerische Einstieg wurde gekürzt, weil Femtosekunden und Nobelpreis später genauer erklärt werden; der vollständige Originaltext bleibt erhalten. Quellen nennen unterschiedliche Orte seiner Kindheit – Alexandria auf der Nobelpreis-Website und Desouk in anderen Darstellungen –, daher wird kein Ort genannt. Die Informationen über die Bibliotheca Alexandrina im Abschnitt „Von Alexandria in die Welt“ stammen aus ägyptischen Zeitungen, nicht direkt von der Bibliothek. Die Grafiken sind Illustrationen, keine wissenschaftlichen Fotografien oder Archivbilder."
};
